use infinite_core::*;use std::num::{NonZeroU16,NonZeroU32};
fn n(v:u32)->NonZeroU32{NonZeroU32::new(v).unwrap()}fn small(v:u16)->NonZeroU16{NonZeroU16::new(v).unwrap()}fn p(x:i32,y:i32)->GridPosition{GridPosition{x,y}}
fn world()->(World,EntityId,Vec<EntityId>){let mut w=World::default();let owner=w.spawn(p(0,0)).unwrap();w.configure_health(owner,100,n(100)).unwrap();let targets=[60,20,40].map(|x|{let e=w.spawn(p(x,0)).unwrap();w.configure_health(e,100,n(100)).unwrap();e}).to_vec();(w,owner,targets)}
fn spec(cast:ProjectileCastId,hits:u16,ticks:u16)->ProjectileLaunch{ProjectileLaunch{cast,from:p(0,0),to:p(100,0),activate_at:Tick(1),travel_ticks:small(ticks),radius:0,max_hits:small(hits),damage:n(10),strict_ends:false,require_sight:false}}
fn settle(s:&mut Projectiles,w:&mut World,events:&mut Vec<CombatEvent>,ends:&mut Vec<ProjectileEnd>)->ProjectileReport{s.begin(w).unwrap().step(MAX_PROJECTILES,&mut CombatQueryBudget::new(100000),events,4096,ends,|_,hit|Some(hit.base_damage)).unwrap()}

#[test]
fn ordered_prefix_matches_full_sort_with_rejected_targets_and_ordinal_policy(){
 for quota in [1,8,80,256]{for strict in [false,true]{
  let mut w=World::default();let owner=w.spawn(p(-100,-100)).unwrap();w.configure_health(owner,100,n(100)).unwrap();
  for i in 0..400{let e=w.spawn(p((i*37%110)-5,(i*13%21)-10)).unwrap();w.configure_health(e,1000,n(1000)).unwrap();}
  let sweep=SegmentSweep{from:p(0,0),to:p(100,0),radius:10,strict_ends:strict};let mut frame=SpatialFrame::new(n(16));frame.capture(&w).unwrap();let mut sorted=Vec::new();CombatQueryContext::new(&frame,None).collect_segment(CombatSegmentQuery{sweep,exclude:Some(owner),sight_origin:None},&mut CombatQueryBudget::new(100000),&mut sorted,|_|true).unwrap();
  let mut expected=Vec::new();for h in sorted{if (h.hit.entity.index+expected.len()as u32)%3!=0{expected.push(h.hit.entity);}if expected.len()==quota as usize{break;}}
  let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(1),quota as usize).unwrap();s.launch(&w,ProjectileLaunch{strict_ends:strict,radius:10,..spec(cast,quota,1)}).unwrap();s.seal_cast(cast).unwrap();w.advance_tick().unwrap();let(mut events,mut ends)=(Vec::new(),Vec::new());s.begin(&mut w).unwrap().step(1,&mut CombatQueryBudget::new(100000),&mut events,4096,&mut ends,|_,h|((h.target.index+u32::from(h.ordinal))%3!=0).then_some(n(u32::from(h.ordinal)+1))).unwrap();
  assert_eq!(events.iter().map(|e|e.target).collect::<Vec<_>>(),expected);for(i,e)in expected.into_iter().enumerate(){assert_eq!(w.health(e).unwrap().current,999-i as u32);}
 }}
}

#[test]
fn bounded_work_slices_preserve_complete_event_and_end_order(){
 fn run(limit:usize)->(Vec<CombatEvent>,Vec<ProjectileEnd>,Vec<u32>){let(mut w,owner,t)=world();let mut s=Projectiles::new(n(16));for _ in 0..4{let cast=s.create_cast(&w,owner,small(2),6).unwrap();for _ in 0..2{s.launch(&w,spec(cast,3,4)).unwrap();}s.seal_cast(cast).unwrap();}let(mut events,mut ends)=(Vec::new(),Vec::new());for _ in 0..4{w.advance_tick().unwrap();let mut phase=s.begin(&mut w).unwrap();let mut budget=CombatQueryBudget::new(100000);loop{if phase.step(limit,&mut budget,&mut events,4096,&mut ends,|_,h|Some(h.base_damage)).unwrap().pending==0{break;}}}assert!(s.is_empty());assert_eq!(s.casts(),0);(events,ends,t.iter().map(|&e|w.health(e).unwrap().current).collect())}
 assert_eq!(run(1),run(MAX_PROJECTILES));
}

#[test]
fn ordered_prefix_can_reject_every_candidate_or_accept_only_the_last(){
 let mut w=World::default();let owner=w.spawn(p(0,0)).unwrap();w.configure_health(owner,100,n(100)).unwrap();let targets:Vec<_>=(0..1000).map(|_|{let e=w.spawn(p(50,0)).unwrap();w.configure_health(e,100,n(100)).unwrap();e}).collect();let mut s=Projectiles::new(n(16));
 for tick in 1..=2{let cast=s.create_cast(&w,owner,small(1),1).unwrap();s.launch(&w,ProjectileLaunch{activate_at:Tick(tick),..spec(cast,1,1)}).unwrap();s.seal_cast(cast).unwrap();w.advance_tick().unwrap();let(mut events,mut ends,mut visited)=(Vec::new(),Vec::new(),Vec::new());s.begin(&mut w).unwrap().step(1,&mut CombatQueryBudget::new(100000),&mut events,4096,&mut ends,|_,h|{visited.push(h.target);(tick==2&&Some(&h.target)==targets.last()).then_some(h.base_damage)}).unwrap();assert_eq!(visited,targets);assert_eq!(events.len(),(tick-1)as usize);assert_eq!(ends[0].reason,if tick==1{ProjectileEndReason::Range}else{ProjectileEndReason::HitLimit});assert_eq!(s.casts(),0);}
 assert_eq!(w.health(*targets.last().unwrap()).unwrap().current,90);
}

#[test]
fn exact_capsule_order_caps_and_zero_length_are_independent_of_entity_order(){let mut w=World::default();let ids=[p(50,0),p(20,3),p(20,0),p(-3,0),p(103,0),p(20,-3),p(20,4)].map(|v|w.spawn(v).unwrap());let mut f=SpatialFrame::new(n(16));f.capture(&w).unwrap();let ctx=CombatQueryContext::new(&f,None);let mut out=Vec::new();let q=CombatSegmentQuery{sweep:SegmentSweep{from:p(0,0),to:p(100,0),radius:3,strict_ends:false},exclude:None,sight_origin:None};ctx.collect_segment(q,&mut CombatQueryBudget::new(10000),&mut out,|_|true).unwrap();assert_eq!(out.iter().map(|h|h.hit.entity).collect::<Vec<_>>(),vec![ids[3],ids[2],ids[1],ids[5],ids[0],ids[4]]);ctx.collect_segment(CombatSegmentQuery{sweep:SegmentSweep{strict_ends:true,..q.sweep},..q},&mut CombatQueryBudget::new(10000),&mut out,|_|true).unwrap();assert_eq!(out.iter().map(|h|h.hit.entity).collect::<Vec<_>>(),vec![ids[2],ids[1],ids[5],ids[0]]);ctx.collect_segment(CombatSegmentQuery{sweep:SegmentSweep{from:p(20,0),to:p(20,0),radius:3,strict_ends:true},..q},&mut CombatQueryBudget::new(10000),&mut out,|_|true).unwrap();assert_eq!(out.iter().map(|h|h.hit.entity).collect::<Vec<_>>(),vec![ids[2],ids[1],ids[5]]);}

#[test]
fn capsule_diagonal_boundaries_extremes_and_failure_are_exact(){let mut w=World::default();let on=w.spawn(p(3,4)).unwrap();let off=w.spawn(p(3,5)).unwrap();let origin=w.spawn(p(i32::MIN,i32::MIN)).unwrap();let far=w.spawn(p(i32::MAX,i32::MAX)).unwrap();let mut f=SpatialFrame::new(n(u32::MAX));f.capture(&w).unwrap();let ctx=CombatQueryContext::new(&f,None);let mut out=Vec::new();let mut q=CombatSegmentQuery{sweep:SegmentSweep{from:p(0,0),to:p(6,8),radius:0,strict_ends:false},exclude:None,sight_origin:None};ctx.collect_segment(q,&mut CombatQueryBudget::new(100),&mut out,|_|true).unwrap();assert_eq!(out.iter().map(|h|h.hit.entity).collect::<Vec<_>>(),vec![on]);assert_ne!(off,on);q.sweep=SegmentSweep{from:p(i32::MIN,i32::MIN),to:p(i32::MIN+MAX_SEGMENT_AXIS as i32,i32::MIN+MAX_SEGMENT_AXIS as i32),radius:u32::MAX,strict_ends:false};ctx.collect_segment(q,&mut CombatQueryBudget::new(100),&mut out,|_|true).unwrap();assert!(out.iter().any(|h|h.hit.entity==origin));assert!(!out.iter().any(|h|h.hit.entity==far));assert_eq!(ctx.collect_segment(q,&mut CombatQueryBudget::new(0),&mut out,|_|true),Err(CombatQueryError::WorkLimitExceeded));assert!(out.is_empty());q.sweep.to=p(i32::MAX,i32::MAX);assert_eq!(ctx.collect_segment(q,&mut CombatQueryBudget::new(100),&mut out,|_|true),Err(CombatQueryError::InvalidSegment));assert!(out.is_empty());}

#[test]
fn first_high_speed_sweep_orders_damage_and_releases_sealed_cast(){let(mut w,owner,t)=world();let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(1),3).unwrap();let id=s.launch(&w,spec(cast,3,1)).unwrap();s.seal_cast(cast).unwrap();w.advance_tick().unwrap();let mut events=Vec::new();let mut ends=Vec::new();let report=s.begin(&mut w).unwrap().step(10,&mut CombatQueryBudget::new(10000),&mut events,4096,&mut ends,|_,h|Some(n(h.base_damage.get()*u32::from(h.ordinal+1)))).unwrap();assert_eq!(report.hits,3);assert_eq!(events.iter().map(|e|e.target).collect::<Vec<_>>(),vec![t[1],t[2],t[0]]);assert_eq!(t.iter().map(|&e|w.health(e).unwrap().current).collect::<Vec<_>>(),vec![70,90,80]);assert_eq!(ends,vec![ProjectileEnd{id,cast,reason:ProjectileEndReason::HitLimit}]);assert!(s.is_empty());assert_eq!(s.casts(),0);assert_eq!(s.state(id),Err(ProjectileError::InvalidProjectile));assert!(matches!(s.begin(&mut w),Err(ProjectileError::AlreadyResolved)));}

#[test]
fn per_cast_cap_lets_later_pellets_pass_already_capped_front_targets(){let(mut w,owner,t)=world();let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(1),3).unwrap();let ids:Vec<_>=(0..3).map(|_|s.launch(&w,spec(cast,1,1)).unwrap()).collect();s.seal_cast(cast).unwrap();w.advance_tick().unwrap();let(mut events,mut ends)=(Vec::new(),Vec::new());let report=settle(&mut s,&mut w,&mut events,&mut ends);assert_eq!(report.hits,3);assert_eq!(events.iter().map(|e|e.target).collect::<Vec<_>>(),vec![t[1],t[2],t[0]]);assert_eq!(ends.iter().map(|e|e.id).collect::<Vec<_>>(),ids);assert!(t.iter().all(|&e|w.health(e).unwrap().current==90));assert_eq!(s.casts(),0);}

#[test]
fn one_projectile_never_rehits_overlap_and_owner_death_does_not_retract_commit(){let(mut w,owner,t)=world();let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(4),4).unwrap();let id=s.launch(&w,ProjectileLaunch{radius:5,..spec(cast,4,4)}).unwrap();s.seal_cast(cast).unwrap();w.apply_damage(owner,100).unwrap();let(mut events,mut ends)=(Vec::new(),Vec::new());for _ in 0..4{w.advance_tick().unwrap();settle(&mut s,&mut w,&mut events,&mut ends);}assert_eq!(events.len(),3);assert!(t.iter().all(|&e|w.health(e).unwrap().current==90));assert_eq!(ends,vec![ProjectileEnd{id,cast,reason:ProjectileEndReason::Range}]);}

#[test]
fn query_and_event_backpressure_preserve_current_projectile_then_resume(){let(mut w,owner,t)=world();let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(1),3).unwrap();let id=s.launch(&w,spec(cast,3,1)).unwrap();s.seal_cast(cast).unwrap();w.advance_tick().unwrap();let(mut events,mut ends)=(Vec::new(),Vec::new());{let mut phase=s.begin(&mut w).unwrap();assert_eq!(phase.step(1,&mut CombatQueryBudget::new(0),&mut events,4096,&mut ends,|_,h|Some(h.base_damage)),Err(ProjectileError::Query(CombatQueryError::WorkLimitExceeded)));assert_eq!(phase.step(1,&mut CombatQueryBudget::new(10000),&mut events,1,&mut ends,|_,h|Some(h.base_damage)),Err(ProjectileError::EventLimit));}assert!(events.is_empty()&&ends.is_empty());assert!(t.iter().all(|&e|w.health(e).unwrap().current==100));assert_eq!(s.state(id).unwrap().steps,0);assert_eq!(settle(&mut s,&mut w,&mut events,&mut ends).hits,3);assert_eq!(events.len(),3);}

#[test]
fn earlier_projectile_commit_is_not_replayed_after_later_event_limit(){let(mut w,owner,t)=world();let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(2),2).unwrap();for _ in 0..2{s.launch(&w,spec(cast,1,1)).unwrap();}s.seal_cast(cast).unwrap();w.advance_tick().unwrap();let(mut events,mut ends)=(Vec::new(),Vec::new());let mut phase=s.begin(&mut w).unwrap();assert_eq!(phase.step(2,&mut CombatQueryBudget::new(10000),&mut events,1,&mut ends,|_,h|Some(h.base_damage)),Err(ProjectileError::EventLimit));assert_eq!(events.len(),1);let first=events[0];events.clear();let report=phase.step(2,&mut CombatQueryBudget::new(10000),&mut events,1,&mut ends,|_,h|Some(h.base_damage)).unwrap();assert_eq!((report.hits,report.pending),(1,0));assert_eq!(events[0].target,first.target);assert_eq!(ends.len(),2);drop(phase);assert_eq!(w.health(t[1]).unwrap().current,80);}

#[test]
fn destroyed_owner_generation_cancel_and_slot_reuse_do_not_damage_new_owner(){let(mut w,owner,t)=world();let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(1),1).unwrap();let id=s.launch(&w,spec(cast,1,1)).unwrap();s.seal_cast(cast).unwrap();w.despawn(owner).unwrap();let new=w.spawn(p(0,0)).unwrap();assert_eq!(new.index,owner.index);assert_ne!(new.generation,owner.generation);w.configure_health(new,100,n(100)).unwrap();w.advance_tick().unwrap();let(mut events,mut ends)=(Vec::new(),Vec::new());settle(&mut s,&mut w,&mut events,&mut ends);assert!(events.is_empty());assert_eq!(ends[0].reason,ProjectileEndReason::OwnerGone);let cast=s.create_cast(&w,new,small(1),1).unwrap();let next=s.launch(&w,ProjectileLaunch{activate_at:Tick(2),..spec(cast,1,1)}).unwrap();assert_eq!(next.index,id.index);assert_ne!(next.generation,id.generation);assert_eq!(s.cancel(id),Err(ProjectileError::InvalidProjectile));assert_eq!(s.cancel_cast(cast).unwrap().len(),1);assert!(s.is_empty());assert!(t.iter().all(|&e|w.health(e).unwrap().current==100));}

#[test]
fn delayed_activation_can_skip_idle_time_but_not_an_active_sweep(){let(mut w,owner,_)=world();let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(1),3).unwrap();let id=s.launch(&w,ProjectileLaunch{activate_at:Tick(5),..spec(cast,3,2)}).unwrap();s.seal_cast(cast).unwrap();for _ in 0..5{w.advance_tick().unwrap();}let(mut events,mut ends)=(Vec::new(),Vec::new());settle(&mut s,&mut w,&mut events,&mut ends);assert_eq!(s.state(id).unwrap().steps,1);w.advance_tick().unwrap();w.advance_tick().unwrap();assert!(matches!(s.begin(&mut w),Err(ProjectileError::SkippedTick)));s.cancel(id).unwrap();settle(&mut s,&mut w,&mut events,&mut ends);}

#[test]
fn reserved_cast_capacity_and_invalid_admission_do_not_allocate_flights(){let(w,owner,_)=world();let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(2),1).unwrap();assert_eq!(s.launch(&w,spec(cast,2,1)),Err(ProjectileError::CastReservationFull));assert!(s.is_empty());assert_eq!(s.launch(&w,ProjectileLaunch{to:p(MAX_SEGMENT_AXIS as i32+1,0),..spec(cast,1,1)}),Err(ProjectileError::Query(CombatQueryError::InvalidSegment)));assert_eq!(s.launch(&w,ProjectileLaunch{activate_at:Tick(u64::MAX),travel_ticks:small(2),..spec(cast,1,1)}),Err(ProjectileError::TimeExhausted));s.seal_cast(cast).unwrap();assert_eq!(s.casts(),0);}

#[test]
fn shielded_projectile_emits_real_zero_damage_feedback_and_client_decodes(){let(mut w,owner,t)=world();w.grant_shield(ShieldSpec{source:owner,target:t[1],duration:None,profile:ShieldProfile::Absorb{capacity:n(15)}}).unwrap();let mut s=Projectiles::new(n(16));let cast=s.create_cast(&w,owner,small(1),1).unwrap();s.launch(&w,spec(cast,1,1)).unwrap();s.seal_cast(cast).unwrap();w.advance_tick().unwrap();let(mut events,mut ends)=(Vec::new(),Vec::new());settle(&mut s,&mut w,&mut events,&mut ends);assert_eq!(w.health(t[1]).unwrap().current,100);assert_eq!(events.len(),1);let mut f=CombatFrame::new(n(64));f.capture(&w,&events).unwrap();let mut sender=CombatSyncSender::new_shielded(1,CombatSyncConfig::default()).unwrap();sender.observe(&f,ViewRect{min:p(-10,-10),max:p(110,10)}).unwrap();let mut replica=CombatReplica::new(1);let report=replica.apply(sender.prepare().unwrap().unwrap()).unwrap();let feedback:Vec<_>=replica.drain_feedback().collect();assert_eq!(feedback[0].kind,CombatFeedbackKind::Hit{damage:0,remaining:100});sender.acknowledge_packet(&report.acknowledgement()).unwrap();}

#[test]
fn optional_sight_reuses_static_movement_rule_before_damage(){let mut map=CollisionMap::new(p(0,0),n(8),n(8),n(16)).unwrap();map.set_blocked(3,3,true).unwrap();let mut w=World::with_map(DEFAULT_TICK_MS,map);let owner=w.spawn(p(24,56)).unwrap();let behind=w.spawn(p(72,56)).unwrap();for e in [owner,behind]{w.configure_health(e,100,n(100)).unwrap();}let mut s=Projectiles::new(n(32));let cast=s.create_cast(&w,owner,small(1),1).unwrap();s.launch(&w,ProjectileLaunch{from:p(24,56),to:p(100,56),require_sight:true,..spec(cast,1,1)}).unwrap();s.seal_cast(cast).unwrap();w.advance_tick().unwrap();let(mut events,mut ends)=(Vec::new(),Vec::new());settle(&mut s,&mut w,&mut events,&mut ends);assert!(events.is_empty());assert_eq!(w.health(behind).unwrap().current,100);assert_eq!(ends[0].reason,ProjectileEndReason::Range);}
